import{_ as e,H as t,f as i,i as l}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"第九章：代码审查和优化","description":"学会让 Claude 做代码审查","frontmatter":{"title":"第九章：代码审查和优化","description":"学会让 Claude 做代码审查"},"headers":[],"relativePath":"guide/3-practical-workflows/09-code-review.md","filePath":"guide/3-practical-workflows/09-code-review.md"}'),o={name:"guide/3-practical-workflows/09-code-review.md"};function s(r,a,d,n,c,p){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="第九章-代码审查和优化" tabindex="-1">第九章：代码审查和优化 <a class="header-anchor" href="#第九章-代码审查和优化" aria-label="Permalink to &quot;第九章：代码审查和优化&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会让 Claude 帮你审查代码质量并给出优化建议。</p></div><h2 id="代码审查是什么" tabindex="-1">代码审查是什么？ <a class="header-anchor" href="#代码审查是什么" aria-label="Permalink to &quot;代码审查是什么？&quot;">​</a></h2><p>代码审查是检查代码质量的过程，找出：</p><ul><li>潜在 bug</li><li>安全风险</li><li>可读性问题</li><li>性能问题</li></ul><h2 id="让-claude-审查代码" tabindex="-1">让 Claude 审查代码 <a class="header-anchor" href="#让-claude-审查代码" aria-label="Permalink to &quot;让 Claude 审查代码&quot;">​</a></h2><h3 id="审查整个文件" tabindex="-1">审查整个文件 <a class="header-anchor" href="#审查整个文件" aria-label="Permalink to &quot;审查整个文件&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请审查这个文件的代码问题</span></span></code></pre></div><h3 id="问优化建议" tabindex="-1">问优化建议 <a class="header-anchor" href="#问优化建议" aria-label="Permalink to &quot;问优化建议&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有哪些地方可以优化？</span></span></code></pre></div><h2 id="claude-常发现的问题" tabindex="-1">Claude 常发现的问题 <a class="header-anchor" href="#claude-常发现的问题" aria-label="Permalink to &quot;Claude 常发现的问题&quot;">​</a></h2><ol><li><strong>命名问题</strong>：变量名 <code>x</code>、<code>temp</code> 不够清晰</li><li><strong>重复代码</strong>：多处重复相似的逻辑</li><li><strong>安全问题</strong>：SQL 注入、密码明文等</li><li><strong>性能问题</strong>：循环效率、数据库查询</li></ol><h2 id="逐个讨论" tabindex="-1">逐个讨论 <a class="header-anchor" href="#逐个讨论" aria-label="Permalink to &quot;逐个讨论&quot;">​</a></h2><p>不要一次接受所有修改建议，逐个问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先修复命名问题，其他的先不动</span></span></code></pre></div><p>这样你可以控制改动的范围。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>有代码仓库。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude 说的对不对？</strong></p><p>A: 你是最终决策者，保持批判思维。</p><p><strong>Q: 优化建议太多了？</strong></p><p>A: 优先处理高风险问题。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>找一段旧代码让 Claude 审查，并实施它的优化建议。</p><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何让 Claude 帮你处理 Git 操作。</p><p><a href="/guide/3-practical-workflows/10-git-operations.html">👉 第十章：Git 操作辅助</a></p>',28)])])}const b=e(o,[["render",s]]);export{u as __pageData,b as default};
